<script setup lang="ts">
import {ref,watch} from 'vue';
import {useBusinessStore,businessApi} from '../stores/business';
const props=defineProps<{readonly?:boolean}>(),business=useBusinessStore();
type Spec={name:string;kind:string;trigger:Record<string,unknown>;timezone:string;calendarPolicy:string;params:Record<string,unknown>;recipients:Array<Record<string,string>>;approvedEffects:string[]};
type Job={id:string;ownerId:string;version:number;status:string;spec:Spec;nextRunAt:string|null;lastRunAt?:string;lastRunStatus?:string};
type Plan={id:string;action:string;jobId:string;spec:Spec;futureOccurrences:Array<{at:string;local:string}>;sample:{text:string;scope:{username:string}};effects:string[];expiresAt:string};
const open=ref(false),busy=ref(false),error=ref(''),jobs=ref<Job[]>([]),templates=ref<Record<string,string>>({}),plan=ref<Plan>(),detail=ref<{job:Job;runs:Array<{id:string;occurrenceLocal:string;status:string;attempt:number;error?:string;sourceRevision?:string;frozenPayload:Array<{output:{text:string}}>;resultRefs:unknown[]}>;audit:unknown[]}>(),results=ref<Array<{id:string;title:string;text:string}>>([]);
const kind=ref('daily_report'),name=ref(''),time=ref('20:30'),trigger=ref('daily'),cron=ref('30 20 * * *'),weekdays=ref([1]),offset=ref(30),at=ref(''),calendar=ref('all_days'),threshold=ref<number>(),target=ref('self'),targetValue=ref(''),inbox=ref(true),editing=ref<Job>(),pack=ref('');
type Pref={enabled:boolean;quietStart:string;quietEnd:string;categories:string[];maxPerDay:number;maxPerEvent:number;minIntervalMinutes:number};const preference=ref<Pref>();
const states:Record<string,string>={active:'运行中',paused:'已暂停',suspended:'连续失败 · 已暂停',archived:'已归档',needs_authorization:'需重新授权',pending:'待执行',running:'执行中',success:'已保存',failed:'失败 · 可回查',skipped:'已跳过',unknown:'正在对账'};
function triggerText(s:Spec){const t=s.trigger;return t.type==='duty'?'正式班次前 '+t.minutesBefore+' 分钟':t.type==='once'?date(String(t.at)):t.type==='cron'?'Cron '+t.expression:(t.type==='weekly'?'每周 '+String(t.weekdays):'每日')+' '+t.time;}
const recipientsText=(s:Spec)=>s.recipients.map(r=>r.kind==='user'?r.userId:r.kind==='role'?'角色 '+r.role:'班级 '+r.className).join('、');
const date=(s:string|null|undefined)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'无';
async function work(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function refresh(){const r=await businessApi<{jobs:Job[];templates:Record<string,string>}>('proxy/scheduled-jobs');jobs.value=r.jobs;templates.value=r.templates;preference.value=(await businessApi<{preference:Pref}>('proxy/reminder-preferences')).preference;results.value=(await businessApi<{results:typeof results.value}>('proxy/scheduled-results')).results;}
async function show(){open.value=true;await work(refresh);}
function edit(j:Job){editing.value=j;kind.value=j.spec.kind;name.value=j.spec.name;trigger.value=String(j.spec.trigger.type);time.value=String(j.spec.trigger.time||'20:30');weekdays.value=j.spec.trigger.weekdays as number[]||[1];offset.value=Number(j.spec.trigger.minutesBefore??30);cron.value=String(j.spec.trigger.expression||'30 20 * * *');at.value=j.spec.trigger.at?new Date(String(j.spec.trigger.at)).toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).replace(' ','T').slice(0,16):'';calendar.value=j.spec.calendarPolicy;threshold.value=j.spec.params.thresholdHours as number|undefined;inbox.value=j.spec.approvedEffects.includes('inbox');target.value='existing';plan.value=undefined;}
async function preview(action='create',job?:Job){if(props.readonly){error.value='请切换任务模式设置或修改规则';return;}await work(async()=>{
 const recipients=target.value==='existing'&&editing.value?editing.value.spec.recipients:target.value==='self'?[{kind:'user',userId:business.profile!.username}]:[{kind:target.value,...(target.value==='user'?{userId:targetValue.value}:target.value==='class'?{className:targetValue.value}:{role:targetValue.value})}];
 const spec={name:name.value||templates.value[kind.value],kind:kind.value,timezone:'Asia/Shanghai',trigger:trigger.value==='cron'?{type:'cron',expression:cron.value}:trigger.value==='once'?{type:'once',at:at.value+':00+08:00'}:trigger.value==='duty'?{type:'duty',minutesBefore:offset.value}:trigger.value==='weekly'?{type:'weekly',time:time.value,weekdays:weekdays.value}:{type:'daily',time:time.value},calendarPolicy:calendar.value,params:kind.value==='due_followup'&&threshold.value?{thresholdHours:threshold.value}:{},recipients,approvedEffects:inbox.value?['report','inbox']:['report']};
 const j=job||editing.value;plan.value=(await businessApi<{plan:Plan}>('proxy/scheduled-jobs/preview',{scopeKey:business.scopeKey,action:action==='create'&&j?'change':action,...(j?{jobId:j.id,expectedVersion:j.version}:{}),...(['create','change'].includes(action)?{spec}:{}),reason:'本人通过任务面板核对确认'})).plan;
 });}
async function confirm(){if(props.readonly||!plan.value)return;await work(async()=>{await businessApi('proxy/scheduled-jobs/confirm',{scopeKey:business.scopeKey,planId:plan.value!.id});plan.value=undefined;editing.value=undefined;await refresh();});}
async function inspect(j:Job){await work(async()=>{detail.value=await businessApi('proxy/scheduled-jobs/'+j.id);});}
async function savePreference(){if(props.readonly||!preference.value)return;await work(async()=>{await businessApi('proxy/reminder-preferences',{...preference.value,scopeKey:business.scopeKey});await refresh();});}
async function preparation(){await work(async()=>{pack.value=(await businessApi<{result:{text:string}}>('proxy/preparation-pack')).result.text;});}
watch(()=>business.scopeKey,()=>{open.value=false;plan.value=undefined;detail.value=undefined;results.value=[];jobs.value=[];pack.value='';});
watch(()=>props.readonly,()=>{plan.value=undefined;});
</script>
<template>
 <div v-if="business.connected" class="jobs-entry"><button type="button" @click="show">定时任务与提醒</button><span>主系统服务端执行 · Asia/Shanghai</span></div>
 <div v-if="open&&business.connected" class="jobs-mask" @click.self="open=false"><section class="jobs-panel" role="dialog" aria-modal="true" aria-label="定时任务与提醒"><header><b>定时任务与提醒</b><button :disabled="busy" @click="work(refresh)">刷新</button><button aria-label="关闭定时任务" @click="open=false">关闭</button></header>
  <p v-if="error" role="alert">{{error}}</p><p v-if="readonly">当前是聊天模式，可查规则与结果。修改规则请切换任务模式。</p>
  <div v-for="j in jobs" :key="j.id" class="jobs-row"><b>{{j.spec.name}} · {{states[j.status]||j.status}} · v{{j.version}}</b><p>{{templates[j.spec.kind]||j.spec.kind}} · {{j.spec.timezone}} · {{triggerText(j.spec)}} · {{j.spec.calendarPolicy==='teaching_days'?'仅教学日':'按规则日期'}} · 接收 {{recipientsText(j.spec)}}</p><p>{{j.ownerId}} · 下次 {{date(j.nextRunAt)}} · 最近 {{states[j.lastRunStatus||'']||j.lastRunStatus||'未运行'}}</p><button @click="inspect(j)">结果与审计</button><template v-if="!readonly&&j.ownerId===business.profile?.username&&j.status!=='archived'"><button @click="edit(j)">修改</button><button @click="preview(j.status==='active'?'pause':'resume',j)">{{j.status==='active'?'暂停':'恢复'}}</button><button @click="preview('run_now',j)">立即执行</button><button @click="preview('archive',j)">归档</button></template></div>
  <form v-if="!readonly" class="jobs-form" @submit.prevent="preview()"><h3>{{editing?'修改规则':'新增规则'}}</h3><label>模板<select v-model="kind"><option v-for="(label,k) in templates" :key="k" :value="k">{{label}}</option></select></label><label>名称<input v-model="name" maxlength="120" placeholder="留空使用模板名称"></label><label>触发方式<select v-model="trigger" aria-label="触发方式"><option value="daily">每天</option><option value="weekly">每周</option><option value="once">指定时间</option><option value="cron">高级 Cron（受限）</option><option v-if="kind==='duty_reminder'" value="duty">正式班次前</option></select></label><label v-if="trigger==='daily'||trigger==='weekly'">北京时间<input v-model="time" type="time" required></label><label v-if="trigger==='weekly'">星期<select v-model="weekdays" multiple><option v-for="(d,i) in ['周日','周一','周二','周三','周四','周五','周六']" :value="i" :key="i">{{d}}</option></select></label><label v-if="trigger==='cron'">高级 Cron（分 时 * * 星期）<input v-model="cron" required maxlength="40" placeholder="30 20 * * 1,3,5"></label><label v-if="trigger==='once'">北京时间<input v-model="at" type="datetime-local" required></label><label v-if="trigger==='duty'">提前分钟<input v-model.number="offset" type="number" min="0" max="120"></label><label>校历策略<select v-model="calendar"><option value="all_days">每天 / 正式班次日期</option><option value="teaching_days">仅校历确认的教学日</option></select></label><label v-if="kind==='due_followup'">人工授权处理时限（小时，可留空仅按 dueAt）<input v-model.number="threshold" type="number" min="1" max="720"></label><label>接收范围<select v-model="target" aria-label="接收范围"><option value="self">本人</option><option v-if="editing" value="existing">保留原对象</option><template v-if="business.profile?.identity==='admin'"><option value="user">指定账号</option><option value="class">班级</option><option value="role">角色</option></template></select></label><label v-if="!['self','existing'].includes(target)">账号 / 班级 / 角色<input v-model="targetValue" placeholder="角色：admin / volunteer / student"></label><label><input v-model="inbox" type="checkbox">保存结果并发送站内提醒</label><button :disabled="busy">预览未来时间和样例</button><button v-if="editing" type="button" @click="editing=undefined;target='self'">取消修改</button></form>
  <section v-if="plan" class="jobs-preview"><h3>核对后确认：{{plan.action}} · {{plan.spec.name}}</h3><p>时区 {{plan.spec.timezone}} · 效果 {{plan.effects.join('、')}} · 有效至 {{date(plan.expiresAt)}}</p><p>接收对象 {{JSON.stringify(plan.spec.recipients)}}</p><ol><li v-for="o in plan.futureOccurrences" :key="o.at">{{o.local}}（UTC {{o.at}}）</li></ol><p v-if="!plan.futureOccurrences.length">无已安排的未来时间；此方案仅执行所选管理动作。</p><pre>{{plan.sample.text}}</pre><button :disabled="busy||readonly" @click="confirm">本人确认此规则操作</button><button @click="plan=undefined">取消</button></section>
  <section v-if="detail"><h3>{{detail.job.spec.name}} 执行记录</h3><div v-for="r in detail.runs" :key="r.id" class="jobs-row"><b>{{r.occurrenceLocal}} · {{states[r.status]||r.status}}</b><p>{{r.id}} · 尝试 {{r.attempt}} · {{r.error||''}}</p><details><summary>冻结结果与业务回执</summary><p>来源版本 {{r.sourceRevision||'未生成'}}</p><pre v-for="(f,i) in r.frozenPayload" :key="i">{{f.output.text}}</pre><pre>{{JSON.stringify(r.resultRefs,null,2)}}</pre></details></div><details><summary>规则审计</summary><pre>{{JSON.stringify(detail.audit,null,2)}}</pre></details></section>
  <section><h3>已保存的事实结果</h3><details v-for="r in results" :key="r.id"><summary>{{r.title}} · {{r.id}}</summary><pre>{{r.text}}</pre></details><button :disabled="busy" @click="preparation">查看下次使用准备包</button><pre v-if="pack">{{pack}}</pre></section>
  <form v-if="preference" class="jobs-form" @submit.prevent="savePreference"><h3>本人提醒偏好</h3><label><input type="checkbox" v-model="preference.enabled">启用站内提醒</label><label>静默开始<input type="time" v-model="preference.quietStart"></label><label>静默结束<input type="time" v-model="preference.quietEnd"></label><label>每日上限<input type="number" min="1" max="50" v-model.number="preference.maxPerDay"></label><label>同一依据最多提醒次数<input type="number" min="1" max="20" v-model.number="preference.maxPerEvent"></label><label>最短间隔（分钟）<input type="number" min="0" max="1440" v-model.number="preference.minIntervalMinutes"></label><label v-for="(v,k) in templates" :key="k"><input type="checkbox" :value="k" v-model="preference.categories">{{v}}</label><button :disabled="busy||readonly">保存本人偏好</button></form>
 </section></div>
</template>
<style scoped>
.jobs-entry{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:6px 20px;font-size:12px;border-bottom:1px solid var(--border)}button{border:1px solid var(--border-strong);background:var(--surface-2);color:var(--text);padding:7px 10px;border-radius:7px;cursor:pointer}button:disabled{opacity:.5}.jobs-mask{position:fixed;inset:0;z-index:70;background:#0006;padding:4dvh 16px;display:flex;justify-content:center}.jobs-panel{width:min(940px,100%);max-height:90dvh;overflow:auto;padding:20px;background:var(--surface);color:var(--text);border-radius:14px}.jobs-panel header{display:flex;align-items:center;gap:10px;position:sticky;top:0;background:var(--surface);padding:6px;z-index:2}.jobs-panel header b{margin-right:auto}.jobs-row,.jobs-preview{border:1px solid var(--border);padding:12px;border-radius:8px;margin:10px 0}.jobs-row button{margin-right:6px}.jobs-form{display:flex;flex-wrap:wrap;gap:12px;border-block:1px solid var(--border);padding:15px 0;margin:16px 0}.jobs-form h3{width:100%;margin:0}.jobs-form label{display:grid;gap:5px;font-size:13px;min-width:120px}.jobs-form input,.jobs-form select{border:1px solid var(--border-strong);background:var(--surface-2);color:var(--text);padding:7px;border-radius:6px;max-width:100%}.jobs-form input[type=checkbox]{width:16px}.jobs-panel pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;font-size:13px;line-height:1.7}.jobs-panel [role=alert]{color:var(--danger)}
</style>
